CREATE FUNCTION public.finance_record_usage(_row jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
INSERT INTO public.finance_usage(event_key,occurred_at,provider,model,service,product,user_id,transaction_id,status,input_tokens,output_tokens,cached_input_tokens,reasoning_tokens,seconds,finalized,estimates,pricing_snapshot)
VALUES(_row->>'event_key',(_row->>'occurred_at')::timestamptz,_row->>'provider',_row->>'model',_row->>'service',_row->>'product',(_row->>'user_id')::uuid,_row->>'transaction_id',_row->>'status',(_row->>'input_tokens')::bigint,(_row->>'output_tokens')::bigint,(_row->>'cached_input_tokens')::bigint,(_row->>'reasoning_tokens')::bigint,(_row->>'seconds')::numeric,(_row->>'finalized')::boolean,_row->'estimates',_row->'pricing_snapshot')
ON CONFLICT(event_key) DO UPDATE SET status=excluded.status,input_tokens=excluded.input_tokens,output_tokens=excluded.output_tokens,cached_input_tokens=excluded.cached_input_tokens,reasoning_tokens=excluded.reasoning_tokens,seconds=excluded.seconds,finalized=excluded.finalized,estimates=excluded.estimates,pricing_snapshot=excluded.pricing_snapshot WHERE NOT finance_usage.finalized;
END; $$;
REVOKE ALL ON FUNCTION public.finance_record_usage(jsonb) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.finance_record_usage(jsonb) TO service_role;
ALTER TABLE public.finance_usage ADD CONSTRAINT finance_usage_nonnegative CHECK ((input_tokens IS NULL OR input_tokens>=0) AND (output_tokens IS NULL OR output_tokens>=0) AND (cached_input_tokens IS NULL OR cached_input_tokens>=0) AND (reasoning_tokens IS NULL OR reasoning_tokens>=0) AND (seconds IS NULL OR seconds>=0));